// @ts-check
// tools/sbom.mjs: one CycloneDX SBOM per shipped lockfile (skill, Forge backend, Forge UI) for a release,
// generated by `npm sbom` from the committed lockfile, runtime dependencies only.
import { test, after } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { gitRepo, removeDir, tempDir } from './_fixture.mjs';

const TOOL = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..', 'tools', 'sbom.mjs');

/** @type {string[]} */
const dirs = [];
after(() => { for (const d of dirs) removeDir(d); });

/** @param {string} name @param {string} version @param {boolean} [withDeps] */
function pkg(name, version, withDeps = false) {
  const manifest = {
    name, version, private: true,
    ...(withDeps ? { dependencies: { 'left-pad': '^1.3.0' }, devDependencies: { 'is-odd': '^3.0.1' } } : {}),
  };
  const lock = {
    name, version, lockfileVersion: 3, requires: true,
    packages: {
      '': manifest,
      ...(withDeps ? {
        'node_modules/left-pad': {
          version: '1.3.0', resolved: 'https://registry.npmjs.org/left-pad/-/left-pad-1.3.0.tgz',
          integrity: 'sha512-XI5MPzVNApjAyhQzphX8BkmKsKUxD4LdyK24iZeQEmBxOL1ojLOQ6D3Gw5wNn4Ia0ZsIJ8B1a8OvQi/5WvDxQ==',
          license: 'WTFPL',
        },
        'node_modules/is-odd': {
          version: '3.0.1', resolved: 'https://registry.npmjs.org/is-odd/-/is-odd-3.0.1.tgz',
          integrity: 'sha512-CQpnWPrDwmP1+SMHXZhtLtJv90yiyVfluGsX5iNCVkrhQtU3TQHsUWPG9wkdk9Lgd5yNpAg9jQEo90CBaXgWMA==',
          dev: true,
        },
      } : {}),
    },
  };
  return { manifest: JSON.stringify(manifest, null, 2) + '\n', lock: JSON.stringify(lock, null, 2) + '\n' };
}

/** A repo shaped like Dowser's: the skill at the root, the Forge app and its UI below. @param {string} version */
function dowserLike(version, rootVersion = version) {
  const root = tempDir('sbom');
  dirs.push(root);
  const top = pkg('dowser', rootVersion);
  const forge = pkg('dowser-forge', '0.1.0', true);
  const ui = pkg('dowser-forge-ui', '0.1.0');
  gitRepo(root, {
    'skill/SKILL.md': `---\nname: dowser\nversion: ${version}\n---\n# Dowser\n`,
    'package.json': top.manifest, 'package-lock.json': top.lock,
    'forge/package.json': forge.manifest, 'forge/package-lock.json': forge.lock,
    'forge/static/app/package.json': ui.manifest, 'forge/static/app/package-lock.json': ui.lock,
  });
  return root;
}

/** @param {string[]} args */
function run(args) {
  const r = spawnSync(process.execPath, [TOOL, ...args], { encoding: 'utf8' });
  return { code: r.status, out: r.status === 0 ? JSON.parse(r.stdout) : undefined, err: r.stderr };
}

test('writes one CycloneDX SBOM per lockfile, named by release, runtime dependencies only', () => {
  const root = dowserLike('1.2.3');
  const out = join(root, '..', `${root.split(/[\\/]/).pop()}-out`);
  dirs.push(out);
  const r = run(['--root', root, '--out', out]);
  assert.equal(r.code, 0, r.err);
  assert.equal(r.out.release, 'v1.2.3');
  assert.deepEqual(r.out.files.map((/** @type {any} */ f) => f.target), ['skill', 'forge', 'forge-ui']);
  for (const f of r.out.files) {
    const bom = JSON.parse(readFileSync(f.file, 'utf8'));
    assert.equal(bom.bomFormat, 'CycloneDX');
    assert.match(f.file, new RegExp(`dowser-${f.target}-v1\\.2\\.3\\.cdx\\.json$`));
    assert.equal(f.components, (bom.components ?? []).length);
  }
  const forge = JSON.parse(readFileSync(r.out.files[1].file, 'utf8'));
  assert.deepEqual(forge.components.map((/** @type {any} */ c) => `${c.name}@${c.version}`), ['left-pad@1.3.0'], 'dev dependency omitted');
  assert.equal(r.out.files[0].components, 0, 'the skill has zero runtime dependencies');
});

test('refuses when the skill and package.json disagree on the version', () => {
  const scratch = tempDir('sbom-x');
  dirs.push(scratch);
  const r = run(['--root', dowserLike('1.2.3', '1.0.0'), '--out', join(scratch, 'o')]);
  assert.equal(r.code, 3);
  assert.match(r.err, /1\.2\.3.*1\.0\.0|1\.0\.0.*1\.2\.3/);
});

test('refuses an uncommitted lockfile unless --allow-dirty', () => {
  const root = dowserLike('1.2.3');
  const lock = join(root, 'forge', 'package-lock.json');
  writeFileSync(lock, readFileSync(lock, 'utf8') + '\n');
  const out = join(tempDir('sbom-d'), 'o');
  dirs.push(dirname(out));
  const refused = run(['--root', root, '--out', out]);
  assert.equal(refused.code, 3);
  assert.match(refused.err, /forge[\\/]package-lock\.json/);
  assert.equal(run(['--root', root, '--out', out, '--allow-dirty']).code, 0);
});

test('a peer range npm calls invalid still yields the SBOM, with the problem reported', () => {
  const root = dowserLike('1.2.3');
  const ui = join(root, 'forge', 'static', 'app');
  const manifest = { name: 'dowser-forge-ui', version: '0.1.0', private: true, dependencies: { react: '^19.0.0', 'old-peer': '^1.0.0' } };
  const lock = {
    name: 'dowser-forge-ui', version: '0.1.0', lockfileVersion: 3, requires: true,
    packages: {
      '': manifest,
      'node_modules/react': { version: '19.0.0', resolved: 'https://registry.npmjs.org/react/-/react-19.0.0.tgz', integrity: 'sha512-AAAA' },
      'node_modules/old-peer': {
        version: '1.0.0', resolved: 'https://registry.npmjs.org/old-peer/-/old-peer-1.0.0.tgz', integrity: 'sha512-BBBB',
        peerDependencies: { react: '^18.2.0' },
      },
    },
  };
  writeFileSync(join(ui, 'package.json'), JSON.stringify(manifest, null, 2) + '\n');
  writeFileSync(join(ui, 'package-lock.json'), JSON.stringify(lock, null, 2) + '\n');
  const scratch = tempDir('sbom-p');
  dirs.push(scratch);
  const r = run(['--root', root, '--out', join(scratch, 'o'), '--allow-dirty']);
  assert.equal(r.code, 0, r.err);
  const f = r.out.files[2];
  assert.equal(f.components, 2);
  assert.ok(f.tree_problems.some((/** @type {string} */ p) => /react@19\.0\.0.*\^18\.2\.0.*old-peer/.test(p)), f.tree_problems.join('\n'));
  assert.match(r.err, /legacy-peer-deps/);
  assert.equal('tree_problems' in r.out.files[1], false, 'absent where npm had no complaint');
});

test('bad arguments exit 2', () => {
  assert.equal(run(['--nope']).code, 2);
});
